// steer's Amp plugin. Amp loads plugins into its own Bun process rather than
// spawning anything, so this file runs the steer binary and turns its answer
// into a rejection or an edited input.
//
// Generated by `steer init --agent amp`, which refuses to overwrite an existing
// file. An edit here survives, and stops matching the binary it talks to: after
// upgrading steer, run that command again with `--force`.
//
// Nothing is imported on purpose: no package has to resolve, so the file works
// the moment it lands.

export const description = "Runs every tool call past the steer ruleset";

const TIMEOUT_MS = 5000;

// The one place steer's fail-open guarantee leaves Rust: every failure returns
// null, and null lets the tool call through untouched.
//
// `Bun.spawn` rather than the `$` on the event context: that one is a reduced
// Bun shell with no stdin channel.
async function ask(payload) {
  try {
    const child = Bun.spawn(
      ["steer", "hook", "--event", "PreToolUse", "--agent", "amp"],
      {
        stdin: new TextEncoder().encode(JSON.stringify(payload)),
        stdout: "pipe",
        stderr: "ignore",
        timeout: TIMEOUT_MS,
      },
    );
    const text = await new Response(child.stdout).text();
    await child.exited;
    const answer = JSON.parse(text);
    return typeof answer.outcome === "string" ? answer : null;
  } catch {
    return null;
  }
}

// Amp puts no directory on the tool call itself; the workspace root is on the
// context as a URI, and older builds have neither. Guarded rather than
// optional-chained: a throw here would reach Amp as a tool error.
function workspace(amp, ctx) {
  try {
    const root = ctx.system.workspaceRoot;
    return root ? amp.helpers.filePathFromURI(root) : process.cwd();
  } catch {
    return process.cwd();
  }
}

export default function (amp) {
  amp.on("tool.call", async (event, ctx) => {
    const answer = await ask({
      tool: event.tool,
      input: event.input,
      cwd: workspace(amp, ctx),
    });
    if (!answer) {
      return { action: "allow" };
    }
    if (answer.outcome === "deny") {
      return { action: "reject-and-continue", message: answer.message };
    }
    if (answer.outcome === "rewrite") {
      // Whether `modify` merges or replaces is undocumented, so the whole
      // input goes back with one field changed, which is right either way.
      return {
        action: "modify",
        input: { ...event.input, cmd: answer.updated_command },
      };
    }
    if (answer.message) {
      // A message on an allowed call is steer reporting a broken config.
      console.error(answer.message);
    }
    return { action: "allow" };
  });
}
